// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 val, uint256 lockTime, uint256 putAmount, uint256 collectAmount) public {
        // Set MinSum when intitalized is false (allowed)
        c.SetMinSum(val);

        // Optionally put some ether so Collect might succeed
        vm.deal(address(c), 1 ether);
        (bool putSuccess,) = address(c).call{value: putAmount}(abi.encodeWithSignature("Put(uint256)", lockTime));

        // Record MinSum before Collect
        uint256 beforeMinSum = c.MinSum();

        // Call Collect
        (bool collectSuccess, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // Rule: MinSum should not have decreased (since it was set when intitalized is false, and bug version might not set it)
        assertTrue(c.MinSum() >= beforeMinSum);
    }
}

